DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_JINDYNASTY' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_JINDYNASTY_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_1','Jin[NEWLINE]Resource-backed cavalry, selected landmarks and tributary logistics[NEWLINE]Domination or Science[NEWLINE][NEWLINE]Build the Landmark and Grassland infrastructure that supports a cavalry army, while balancing stored Horses against paid recruitment. A large horse inventory is a strategic asset; spending it changes the maximum-HP support available to the army.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_2','Use Mounted Villagers and the capital''s starting development opportunity to build food and production. Choose Landmark paths with a longer-term plan and remember that effects follow completed native construction, not a selection click.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_3','Protect the chosen Grassland sites and place useful War Stables within their real range. Compare recruitment''s Horse and Gold cost with the HP benefit of retaining the stockpile. Use Emissaries and Tributaries when their access and diplomatic conditions are available.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_4','Preserve the experienced cavalry force, protect its resource locations and keep recruitment financially sustainable. Use Bribe only with a safe follow-up plan: replacements are Barbarian-controlled threats to both armies, not free Jin soldiers.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_5','- Mounted Villagers combine Worker utility with strong development mobility.[NEWLINE]- Stored Horses support eligible cavalry maximum HP and enable recruitment choices.[NEWLINE]- Landmarks and Tributaries provide several connected economic and military plans.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_6','- Horses, Gold, legal city deployment and prerequisites all constrain recruitment.[NEWLINE]- Pillage can stop a Grassland site''s generation and HP contribution.[NEWLINE]- A selected Landmark is a permanent choice, and the system has several management dependencies.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_7','- Threaten active Grasslands and War Stable approaches.[NEWLINE]- Force the owner to spend reserves before the main cavalry campaign.[NEWLINE]- Use appropriate anti-mounted forces and avoid leaving a valuable cluster vulnerable to an Emissary.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_8','- Treating a Landmark selection as a completed building.[NEWLINE]- Expecting stored Horses to buff every military class or tanks.[NEWLINE]- Assuming Bribe delivers friendly units, or that HP-cap adjustments create free repeated healing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Conical Union: A mobile cavalry army can threaten the network bottlenecks and repairs supporting connected-city yields.[NEWLINE][NEWLINE]The Lantern Fleet: Land cavalry can threaten productive coastal approaches and resource sites beyond the static guarded-city snapshot.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Unrung Bell: Prepared Pikeman-derived territorial defenders can force costly cavalry engagements.[NEWLINE][NEWLINE]The Threshold Court: Rapid reinforcement of a distant House city can deny the isolated target a mobile campaign hoped to overwhelm.');
