INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_BACKGROUND','Build the Landmark and Grassland infrastructure that supports a cavalry army, while balancing stored Horses against paid recruitment. A large horse inventory is a strategic asset; spending it changes the maximum-HP support available to the army.');
