INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_LEADER_BACKGROUND','Build the Landmark and Grassland infrastructure that supports a cavalry army, while balancing stored Horses against paid recruitment. A large horse inventory is a strategic asset; spending it changes the maximum-HP support available to the army.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_JINDYNASTY_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_JIN_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_STRATEGY','Build the Landmark and Grassland infrastructure that supports a cavalry army, while balancing stored Horses against paid recruitment. A large horse inventory is a strategic asset; spending it changes the maximum-HP support available to the army.[NEWLINE][NEWLINE]Use Mounted Villagers and the capital''s starting development opportunity to build food and production. Choose Landmark paths with a longer-term plan and remember that effects follow completed native construction, not a selection click.[NEWLINE][NEWLINE]Protect the chosen Grassland sites and place useful War Stables within their real range. Compare recruitment''s Horse and Gold cost with the HP benefit of retaining the stockpile. Use Emissaries and Tributaries when their access and diplomatic conditions are available.[NEWLINE][NEWLINE]Preserve the experienced cavalry force, protect its resource locations and keep recruitment financially sustainable. Use Bribe only with a safe follow-up plan: replacements are Barbarian-controlled threats to both armies, not free Jin soldiers.');
