INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_LEADER_TEXT_2','Use Mounted Villagers and the capital''s starting development opportunity to build food and production. Choose Landmark paths with a longer-term plan and remember that effects follow completed native construction, not a selection click.[NEWLINE][NEWLINE]Protect the chosen Grassland sites and place useful War Stables within their real range. Compare recruitment''s Horse and Gold cost with the HP benefit of retaining the stockpile. Use Emissaries and Tributaries when their access and diplomatic conditions are available.[NEWLINE][NEWLINE]Preserve the experienced cavalry force, protect its resource locations and keep recruitment financially sustainable. Use Bribe only with a safe follow-up plan: replacements are Barbarian-controlled threats to both armies, not free Jin soldiers.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_JINDYNASTY_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Conical Union: A mobile cavalry army can threaten the network bottlenecks and repairs supporting connected-city yields.[NEWLINE][NEWLINE]The Lantern Fleet: Land cavalry can threaten productive coastal approaches and resource sites beyond the static guarded-city snapshot.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Unrung Bell: Prepared Pikeman-derived territorial defenders can force costly cavalry engagements.[NEWLINE][NEWLINE]The Threshold Court: Rapid reinforcement of a distant House city can deny the isolated target a mobile campaign hoped to overwhelm.');
